package main
import("context";"log";"net";"os";"os/signal";"syscall";"time";"inventory-service/internal/config";"inventory-service/internal/store";"inventory-service/internal/server";inventoryv1 "inventory-service/gen/inventoryv1";"google.golang.org/grpc";"google.golang.org/grpc/health";healthpb "google.golang.org/grpc/health/grpc_health_v1";"google.golang.org/grpc/reflection";"google.golang.org/grpc/status";"github.com/jackc/pgx/v5/pgxpool")
func logger(ctx context.Context,req any,info *grpc.UnaryServerInfo,h grpc.UnaryHandler)(any,error){start:=time.Now();r,e:=h(ctx,req);log.Printf("method=%s code=%s duration=%s",info.FullMethod,status.Code(e),time.Since(start));return r,e}
func recoverer(ctx context.Context,req any,info *grpc.UnaryServerInfo,h grpc.UnaryHandler)(r any,e error){defer func(){if x:=recover();x!=nil{log.Printf("panic: %v",x);e=status.Error(13,"internal error")}}();return h(ctx,req)}
func main(){c:=config.Load();ctx,cancel:=context.WithTimeout(context.Background(),30*time.Second);defer cancel();var db *pgxpool.Pool;for {p,e:=store.Connect(ctx,c.DatabaseURL);if e==nil{db=p;break};if ctx.Err()!=nil{log.Fatal(e)};log.Printf("database unavailable: %v",e);time.Sleep(time.Second)};defer db.Close();l,e:=net.Listen("tcp",":"+c.Port);if e!=nil{log.Fatal(e)};g:=grpc.NewServer(grpc.ChainUnaryInterceptor(recoverer,logger));inventoryv1.RegisterInventoryServiceServer(g,&server.Server{DB:db});h:=health.NewServer();healthpb.RegisterHealthServer(g,h);reflection.Register(g);go g.Serve(l);ch:=make(chan os.Signal,1);signal.Notify(ch,syscall.SIGTERM,syscall.SIGINT);<-ch;g.GracefulStop()}
